def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    cindy_bid = None
    david_bid = None
    highest_prev = 0.0
    second_prev = 0.0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= highest_prev:
                second_prev = highest_prev
                highest_prev = float(bid)
            elif float(bid) > second_prev:
                second_prev = float(bid)
            if oid == 'Cindy':
                cindy_bid = float(bid)
            if oid == 'David':
                david_bid = float(bid)

    guaranteed_units = int(supply // WATER_REQ)
    contested = guaranteed_units <= 1
    abundant = guaranteed_units >= 2

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1
    if contested:
        danger += 2
    elif not abundant:
        danger += 1

    if cindy_bid is None:
        cindy_bid = 118.0
    if david_bid is None:
        david_bid = 82.0

    target = DAILY_SALARY * 0.45

    if danger >= 5:
        target = max(target, cindy_bid + 2.0)
    elif danger >= 3:
        target = max(target, david_bid + 3.0)
        if contested:
            target = max(target, highest_prev + 1.5)
    else:
        if contested:
            target = max(target, david_bid + 1.0)
        else:
            target = max(target, DAILY_SALARY * 0.42)

    if hp >= 8 and no_water_days == 0 and contested and cindy_bid >= DAILY_SALARY * 1.5:
        target = min(target, DAILY_SALARY * 0.55)

    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget)
    elif budget < DAILY_SALARY * 2.0 and danger < 4:
        target = min(target, DAILY_SALARY * 0.85)

    if day >= 8:
        target *= 1.1
    if day >= 9 and danger >= 3:
        target *= 1.1

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 1.15)

    bid = max(0.0, min(float(budget), float(target)))
    return float(round(bid, 4))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    # Extract yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in opponents_status.values():
        if opp['alive']:
            trace = opp.get('previous_trace', {})
            if trace and trace.get('bid') is not None:
                yesterday_bids.append(trace['bid'])
    # Determine target bid based on yesterday's max
    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
        # If we are desperate (low HP) or need to guarantee water, bid just above max_yesterday
        if my_status['hp'] <= 2:
            target_bid = max_yesterday + 2.0
        else:
            # Otherwise, be slightly more conservative but still competitive
            target_bid = max_yesterday + 1.0
    else:
        # First day or no previous data: base on HP
        if my_status['hp'] <= 2:
            target_bid = DAILY_SALARY * 0.9
        elif my_status['hp'] <= 5:
            target_bid = DAILY_SALARY * 0.6
        else:
            target_bid = DAILY_SALARY * 0.4
    # Ensure target does not exceed budget and is not negative
    # Also consider supply: if supply is low, we may need to bid higher
    supply = day_context['supply']
    supply_factor = 1.0
    if supply < 20:
        supply_factor = 1.2
    elif supply > 22:
        supply_factor = 0.9
    target_bid *= supply_factor
    # Cap by remaining budget
    final_bid = min(my_status['budget'], target_bid)
    # Ensure non-negative and reasonable floor
    if my_status['hp'] <= 1:
        # Desperate: bid up to 95% of daily salary or max budget
        final_bid = max(final_bid, DAILY_SALARY * 0.95)
    else:
        final_bid = max(final_bid, 0.0)
    return min(final_bid, my_status['budget'])
